{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "SRT2104, a structurally related thiazole-containing small molecule, had absolute oral bioavailability of 13.8% (range 2–27%) in a Phase 1 human study using an IV microdose reference, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Revefenacin, a close analogue with high transferability, showed absolute oral bioavailability <3% in healthy volunteers and COPD patients, indicating very poor systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor sharing the hydroxyethylene/peptide backbone features, had human oral bioavailability of 0.5% at 40 mg, far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "GHRP-6, a peptide mimetic with multiple amide bonds, had systemic availability ~0.3% in humans after oral administration, demonstrating that peptide-like molecules in this class are poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Lopinavir, a peptidomimetic HIV protease inhibitor with a similar hydroxyethylene core and two benzyl side chains, has low oral bioavailability in humans due to first-pass metabolism and P-glycoprotein efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alvimopan, a small-molecule peptidomimetic with amide and basic amine functionality, has human absolute oral bioavailability of 0.06 (6%), below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Remikiren, a renin inhibitor peptidomimetic, had absolute bioavailability of 0.3% in healthy male volunteers after an 800 mg oral dose, confirming very low oral absorption for this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a peptidomimetic with a hydroxyethylene core, multiple amide bonds, and lipophilic side chains. Highly transferable human absolute-bioavailability data for structurally related peptidomimetics (SRT2104 13.8%, revefenacin <3%, enalkiren 0.5%, GHRP-6 ~0.3%, lopinavir low, alvimopan 6%, remikiren 0.3%) consistently fall below 20%. Although the query is assessed under fed conditions, no evidence supports a food effect large enough to overcome the strong pattern of poor oral bioavailability in this chemical class.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "The fed-state condition was not directly tested in the analogue records; most measurements were fasted or unspecified.",
    "The magnitude of any food effect on this specific peptidomimetic is unknown, though it is unlikely to raise F above 20% given the uniformly low analogue values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

